-- paperclip:migration-compat online_compatible: The new index is the same unique key restricted to rows whose state is not 'resolved', so every write the previous release can make still satisfies it, and that release's untargeted ON CONFLICT DO NOTHING matches a partial unique index as well. The drop and rebuild share one transaction, so no write sees the key unfenced; the table holds one small row per sandbox creation, so the exclusive lock lasts only for that index build.
DROP INDEX "sandbox_creation_operations_owner_idx";--> statement-breakpoint
CREATE UNIQUE INDEX "sandbox_creation_operations_owner_idx" ON "sandbox_creation_operations" USING btree ("company_id","original_environment_id","run_id","request_key") WHERE "sandbox_creation_operations"."state" <> 'resolved';
